const rtdal008233Source0004 = `st_rotate = function(.x, lon0, lat0, north, ...) UseMethod("st_rotate")`

const rtdal008233Source0005 = `st_rotate.stars = function(.x, lon0, lat0, north = TRUE, ...) {
	stopifnot(is.na(st_crs(.x)) || st_is_longlat(.x), 
			  !is_curvilinear(.x), 
			  is.logical(north), 
			  !is.na(north),
			  lat0 <= 90,
			  lat0 >= -90,
			  length(list(...)) == 0)
	if (has_sfc(.x))
		st_set_dimensions(.x, which_sfc(.x), values = rotate(st_geometry(.x), lon0, lat0, north))
	else {
		.x = st_upfront(.x)
		d = dim(.x)
		ccr = rotate(st_coordinates(st_dimensions(.x)[1:2]), lon0, lat0, north)
		st_as_stars(.x, curvilinear = setNames(list(matrix(ccr[,1], d[1], d[2]),
					  matrix(ccr[,2], d[1], d[2])), names(d)[1:2]))
	}
}`

const rtdal008233Source0006 = `st_rotate.sfc = function(.x, lon0, lat0, north = TRUE, ...) {
	r = rapply(.x, rotate, how = "replace", lon0 = lon0, lat0 = lat0, north = north)
	st_set_crs(st_sfc(r, recompute_bbox = TRUE), NA_crs_)
}`

const rtdal008233Source0007 = `st_rotate.sf = function(.x, lon0, lat0, north = TRUE, ...) {
	st_set_geometry(.x, st_rotate(st_geometry(.x), lon0, lat0, north))
}`

