const rtdal008241Source0016 = `as.tbl_cube.stars = function(x, ...) {
    if (!requireNamespace("cubelyr", quietly = TRUE))
        stop("package cubelyr required, please install it first") # nocov
	cleanup = function(y) {
		if (is.list(y))
			seq_along(y)
		else
			y
	}
	dims = lapply(expand_dimensions(x), cleanup)
	cubelyr::tbl_cube(dims, c(unclass(x)))
}`

const rtdal008241Source0017 = `slice.stars <- function(.data, along, index, ..., drop = length(index) == 1) {
  #stopifnot(length(index) == 1)
  if (!requireNamespace("rlang", quietly = TRUE))
    stop("package rlang required, please install it first") # nocov
    
  nd <- length(dim(.data))
  indices <- rep(list(rlang::missing_arg()), nd + 1)
  along = rlang::expr_text(rlang::ensym(along))
  ix = which(along == names(st_dimensions(.data)))[1]
  indices[[ix + 1]] <- index
  indices[["drop"]] <- drop
  
  eval(rlang::expr(.data[!!!indices]))
}`

const rtdal008241Source0018 = "slice.stars_proxy <- function(.data, along, index, ...) {\n  # TODO: add adrop argument, this requires an eager implementation of\n  # adrop.stars_proxy\n\n  # If there are already operations queued, just add to the queue\n  if (!is.null(attr(.data, \"call_list\")) || \n\t  \t(length(.data) == 1 && is.character(.data[[1]]))) # #527\n    return(collect(.data, match.call(), \"slice\", \".data\",\n                   env = parent.frame(), ...))\n\n  # figure out which dimensions are part of the files\n  vecsize <- rev(cumprod(rev(dim(.data))))\n\n  # NOTE: The first set of dimensions corresponds to the dimensions in the\n  # files. The second set of dimensions corresponds to the list of files. It may\n  # be undecided where exactly the break is (at least without reading in the\n  # files) if there are a singleton dimensions, I am not sure if this matters,\n  # for now just assume the maximum index, this should be the safe choice.\n  # Singleton dimensions that are part of files probably need some logic\n  # somewhere else and cannot just be ignored.\n\n  # Can we assume, that all elements of .data are the same?\n  first_concat_dim <- max(which(vecsize == length(.data[[1]])))\n  stopifnot(first_concat_dim > 0)\n  all_dims <- st_dimensions(.data)\n  file_dims <- all_dims[seq_len(first_concat_dim - 1)]\n  concat_dims <- all_dims[first_concat_dim:length(dim(.data))]\n  d_concat_dims <- dim(concat_dims)\n  l_concat_vec <- prod(d_concat_dims)\n\n  # what is the dimension we have to subset\n  ix <- which(names(all_dims) == along) - length(file_dims)\n  stopifnot(length(ix) == 1)\n\n  # if the slice is on file dimensions we have to queue the operation\n  if (ix <= 0)\n    return(collect(.data, match.call(), \"slice\", \".data\",\n                   env = parent.frame(), ...))\n\n  # subset indices for the files, it may be faster to calculate these and not\n  # take them from an array.\n  d <- array(seq_len(l_concat_vec), d_concat_dims)\n  idx <- rep(list(quote(expr = )), length(d_concat_dims))\n  idx[[ix]] <- index\n  vidx <- as.vector(do.call(`[`, c(list(d), idx)))\n\n  # The actual subsetting of files and dimensions\n  file_list_new <- lapply(.data, function(x) x[vidx])\n  all_dims[[along]] <- all_dims[[along]][index]\n\n  # construct stars_proxy\n  st_stars_proxy(as.list(file_list_new), all_dims,\n                 NA_value = attr(.data, \"NA_value\"),\n                 resolutions = attr(.data, \"resolutions\"),\n                 RasterIO = attr(.data, \"RasterIO\"))\n}"

const rtdal008241Source0019 = `as_tibble.stars = function(.x, ..., add_max = FALSE, center = NA) {
    if (!requireNamespace("tibble", quietly = TRUE))
        stop("package tibble required, please install it first") # nocov

	tibble::as_tibble(append(
			st_coordinates(.x, add_max = add_max, center = center),
			lapply(.x, function(y) structure(y, dim = NULL))
		)
	)
}`

const rtdal008241Source0020 = `replace_na.stars = function(data, replace, ...) {
    if (!requireNamespace("tidyr", quietly = TRUE))
        stop("package tidyr required, please install it first") # nocov
    if (!requireNamespace("cubelyr", quietly = TRUE))
        stop("package cubelyr required, please install it first") # nocov
	cb = cubelyr::as.tbl_cube(data)
	d = dim(cb$mets[[1]])
	cb$mets = as.data.frame(lapply(cb$mets, as.vector))
	cb$mets = unclass(tidyr::replace_na(cb$mets, replace, ...))
	for (i in seq_along(cb$mets))
		cb$mets[[i]] = structure(cb$mets[[i]], dim = d)
	st_as_stars(cb$mets, dimensions = get_dims(cb$dims, st_dimensions(data)))
}`

const rtdal008241Source0021 = `replace_na.stars_proxy = function(data, ...) {
	collect(data, match.call(), "replace_na", "data", env = environment())
}`

const rtdal008241Source0022 = `geom_stars = function(mapping = NULL, data = NULL, ..., downsample = 0, sf = FALSE, 
					  na.action = na.pass) {

	if (!requireNamespace("ggplot2", quietly = TRUE))
		stop("package ggplot2 required, please install it first") # nocov
	if (!requireNamespace("tibble", quietly = TRUE))
		stop("package tibble required, please install it first") # nocov

	if (is.null(data)) stop("argument data should be a stars or stars_proxy object")

	for (i in seq_along(data)) {
		if (inherits(data[[i]], "units"))
			data[[i]] = units::drop_units(data[[i]])
	}
	if (inherits(data, "stars_proxy"))
		data = st_as_stars(data, downsample = downsample) # fetches data
	else if (any(downsample > 0))
		data = st_downsample(data, downsample)
	
	all_colors = function (x) {
		is.character(x) && all(nchar(x) %in% c(7, 9) & substr(x, 1, 1) == "#", na.rm = TRUE)
	}
	if (is.null(list(...)$fill) && all_colors(fill <- as.vector(data[[1]])))
		return(geom_stars(mapping = mapping, data = data, sf = sf, na.action = na.action, 
						  ..., fill = fill)) # RETURNS/recurses

	if (is_curvilinear(data) || sf)
		data = st_xy2sfc(data, as_points = FALSE) # removes NA's by default

	d = st_dimensions(data)

	if (has_raster(d) && (is_regular_grid(d) || is_rectilinear(d))) {
		xy = attr(d, "raster")$dimensions
		if (is_regular_grid(d)) {
			mapping = if (is.null(mapping))
					ggplot2::aes(x = !!rlang::sym(xy[1]), y = !!rlang::sym(xy[2]),
						fill = !!rlang::sym(names(data)[1])) 
				else 
           			modifyList( ggplot2::aes(x = !!rlang::sym(xy[1]), y = !!rlang::sym(xy[2]),
						fill = !!rlang::sym(names(data)[1])), mapping) 
			data = na.action(tibble::as_tibble(data))
			ggplot2::geom_raster(mapping = mapping, data = data, ...)
		} else {  # rectilinear: use geom_rect, passing on cell boundaries
			xy_max = paste0(xy, "_max")
			mapping = if (is.null(mapping))
					ggplot2::aes(xmin = !!rlang::sym(xy[1]), ymin = !!rlang::sym(xy[2]),
						xmax = !!rlang::sym(xy_max[1]), ymax = !!rlang::sym(xy_max[2]),
						fill = !!rlang::sym(names(data)[1]))
				else 
					modifyList(ggplot2::aes(xmin = !!rlang::sym(xy[1]), ymin = !!rlang::sym(xy[2]),
						xmax = !!rlang::sym(xy_max[1]), ymax = !!rlang::sym(xy_max[2]),
						fill = !!rlang::sym(names(data)[1])), mapping) 
			data = na.action(tibble::as_tibble(data, add_max = TRUE))
			ggplot2::geom_rect(mapping = mapping, data = data, ...)
		}
	} else if (has_sfc(d)) {
		if (is.null(mapping)) {
			mapping = ggplot2::aes(fill = !!rlang::sym(names(data)[1])) } else {
		        mapping = modifyList( ggplot2::aes(fill = !!rlang::sym(names(data)[1])), mapping) }
		ggplot2::geom_sf(data = st_as_sf(data, long = TRUE), mapping = mapping, ...)
	} else
		stop("geom_stars only works for objects with raster or vector geometries")
						     
}`

