const rtdal008368Source0001 = `map <- function(.x, .f, ...) {
  lapply(.x, .f, ...)
}`

const rtdal008368Source0002 = `map_mold <- function(.x, .f, .mold, ...) {
  out <- vapply(.x, .f, .mold, ..., USE.NAMES = FALSE)
  names(out) <- names(.x)
  out
}`

const rtdal008368Source0003 = `map_lgl <- function(.x, .f, ...) {
  map_mold(.x, .f, logical(1), ...)
}`

const rtdal008368Source0004 = `map_int <- function(.x, .f, ...) {
  map_mold(.x, .f, integer(1), ...)
}`

const rtdal008368Source0005 = `map_dbl <- function(.x, .f, ...) {
  map_mold(.x, .f, double(1), ...)
}`

const rtdal008368Source0006 = `map_chr <- function(.x, .f, ...) {
  map_mold(.x, .f, character(1), ...)
}`

const rtdal008368Source0007 = `map_cpl <- function(.x, .f, ...) {
  map_mold(.x, .f, complex(1), ...)
}`

const rtdal008368Source0008 = `walk <- function(.x, .f, ...) {
  map(.x, .f, ...)
  invisible(.x)
}`

const rtdal008368Source0015 = `map2 <- function(.x, .y, .f, ...) {
  out <- mapply(.f, .x, .y, MoreArgs = list(...), SIMPLIFY = FALSE)
  if (length(out) == length(.x)) {
    set_names(out, names(.x))
  } else {
    set_names(out, NULL)
  }
}`

const rtdal008368Source0016 = `map2_lgl <- function(.x, .y, .f, ...) {
  as.vector(map2(.x, .y, .f, ...), "logical")
}`

