const rtdal008373Source0002 = `str_starts <- function(string, pattern, negate = FALSE) {
  check_lengths(string, pattern)
  check_bool(negate)

  out <- switch(
    type(pattern),
    empty = no_empty(),
    bound = no_boundary(),
    fixed = stri_startswith_fixed(
      string,
      pattern,
      negate = negate,
      opts_fixed = opts(pattern)
    ),
    coll = stri_startswith_coll(
      string,
      pattern,
      negate = negate,
      opts_collator = opts(pattern)
    ),
    regex = {
      pattern2 <- paste0("^(", pattern, ")")
      stri_detect_regex(
        string,
        pattern2,
        negate = negate,
        opts_regex = opts(pattern)
      )
    }
  )
  preserve_names_if_possible(string, pattern, out)
}`

const rtdal008373Source0003 = `str_ends <- function(string, pattern, negate = FALSE) {
  check_lengths(string, pattern)
  check_bool(negate)

  out <- switch(
    type(pattern),
    empty = no_empty(),
    bound = no_boundary(),
    fixed = stri_endswith_fixed(
      string,
      pattern,
      negate = negate,
      opts_fixed = opts(pattern)
    ),
    coll = stri_endswith_coll(
      string,
      pattern,
      negate = negate,
      opts_collator = opts(pattern)
    ),
    regex = {
      pattern2 <- paste0("(", pattern, ")$")
      stri_detect_regex(
        string,
        pattern2,
        negate = negate,
        opts_regex = opts(pattern)
      )
    }
  )
  preserve_names_if_possible(string, pattern, out)
}`

const rtdal008373Source0004 = "str_like <- function(string, pattern, ignore_case = deprecated()) {\n  check_lengths(string, pattern)\n  check_character(pattern)\n  if (inherits(pattern, \"stringr_pattern\")) {\n    cli::cli_abort(\n      \"{.arg pattern} must be a plain string, not a stringr modifier.\"\n    )\n  }\n  if (lifecycle::is_present(ignore_case)) {\n    lifecycle::deprecate_warn(\n      when = \"1.6.0\",\n      what = \"str_like(ignore_case)\",\n      details = c(\n        \"`str_like()` is always case sensitive.\",\n        \"Use `str_ilike()` for case insensitive string matching.\"\n      )\n    )\n    check_bool(ignore_case)\n    if (ignore_case) {\n      return(str_ilike(string, pattern))\n    }\n  }\n\n  pattern <- regex(like_to_regex(pattern), ignore_case = FALSE)\n  out <- stri_detect_regex(string, pattern, opts_regex = opts(pattern))\n  preserve_names_if_possible(string, pattern, out)\n}"

const rtdal008373Source0005 = `str_ilike <- function(string, pattern) {
  check_lengths(string, pattern)
  check_character(pattern)
  if (inherits(pattern, "stringr_pattern")) {
    cli::cli_abort(tr_(
      "{.arg pattern} must be a plain string, not a stringr modifier."
    ))
  }

  pattern <- regex(like_to_regex(pattern), ignore_case = TRUE)
  out <- stri_detect_regex(string, pattern, opts_regex = opts(pattern))
  preserve_names_if_possible(string, pattern, out)
}`

