const rtdal008384Source0003 = `coll <- function(pattern, ignore_case = FALSE, locale = "en", ...) {
  pattern <- as_bare_character(pattern)
  check_bool(ignore_case)
  check_string(locale)

  options <- str_opts_collator(
    ignore_case = ignore_case,
    locale = locale,
    ...
  )

  structure(
    pattern,
    options = options,
    class = c("stringr_coll", "stringr_pattern", "character")
  )
}`

const rtdal008384Source0004 = `str_opts_collator <- function(
  locale = "en",
  ignore_case = FALSE,
  strength = NULL,
  ...
) {
  strength <- strength %||% if (ignore_case) 2L else 3L
  stri_opts_collator(
    strength = strength,
    locale = locale,
    ...
  )
}`

const rtdal008384Source0006 = `regex <- function(
  pattern,
  ignore_case = FALSE,
  multiline = FALSE,
  comments = FALSE,
  dotall = FALSE,
  ...
) {
  pattern <- as_bare_character(pattern)
  check_bool(ignore_case)
  check_bool(multiline)
  check_bool(comments)
  check_bool(dotall)

  options <- stri_opts_regex(
    case_insensitive = ignore_case,
    multiline = multiline,
    comments = comments,
    dotall = dotall,
    ...
  )

  structure(
    pattern,
    options = options,
    class = c("stringr_regex", "stringr_pattern", "character")
  )
}`

const rtdal008384Source0007 = `boundary <- function(
  type = c("character", "line_break", "sentence", "word"),
  skip_word_none = NA,
  ...
) {
  type <- arg_match(type)
  check_bool(skip_word_none, allow_na = TRUE)

  if (identical(skip_word_none, NA)) {
    skip_word_none <- type == "word"
  }

  options <- stri_opts_brkiter(
    type = type,
    skip_word_none = skip_word_none,
    ...
  )

  structure(
    NA_character_,
    options = options,
    class = c("stringr_boundary", "stringr_pattern", "character")
  )
}`

const rtdal008384Source0008 = `opts <- function(x) {
  if (identical(x, "")) {
    stri_opts_brkiter(type = "character")
  } else {
    attr(x, "options")
  }
}`

const rtdal008384Source0014 = `type.character <- function(x, error_call = caller_env()) {
  if (any(is.na(x))) {
    cli::cli_abort(
      tr_("{.arg pattern} can not contain NAs."),
      call = error_call
    )
  }

  if (identical(x, "")) "empty" else "regex"
}`

const rtdal008384Source0015 = `type.default <- function(x, error_call = caller_env()) {
  if (inherits(x, "regex")) {
    # Fallback for rex
    return("regex")
  }

  cli::cli_abort(
    tr_(
      "{.arg pattern} must be a character vector, not {.obj_type_friendly {x}}."
    ),
    call = error_call
  )
}`

