const rtdal008389Source0001 = `str_split <- function(string, pattern, n = Inf, simplify = FALSE) {
  check_lengths(string, pattern)
  check_positive_integer(n)
  check_bool(simplify, allow_na = TRUE)

  if (identical(n, Inf)) {
    n <- -1L
  }

  out <- switch(
    type(pattern),
    empty = stri_split_boundaries(
      string,
      n = n,
      simplify = simplify,
      opts_brkiter = opts(pattern)
    ),
    bound = stri_split_boundaries(
      string,
      n = n,
      simplify = simplify,
      opts_brkiter = opts(pattern)
    ),
    fixed = stri_split_fixed(
      string,
      pattern,
      n = n,
      simplify = simplify,
      opts_fixed = opts(pattern)
    ),
    regex = stri_split_regex(
      string,
      pattern,
      n = n,
      simplify = simplify,
      opts_regex = opts(pattern)
    ),
    coll = stri_split_coll(
      string,
      pattern,
      n = n,
      simplify = simplify,
      opts_collator = opts(pattern)
    )
  )

  preserve_names_if_possible(string, pattern, out)
}`

const rtdal008389Source0004 = `str_split_i <- function(string, pattern, i) {
  check_number_whole(i)

  if (i > 0) {
    out <- str_split(string, pattern, simplify = NA, n = i + 1)
    col <- out[, i]
    if (keep_names(string, pattern)) copy_names(string, col) else col
  } else if (i < 0) {
    i <- abs(i)
    pieces <- str_split(string, pattern)
    last <- function(x) {
      n <- length(x)
      if (i > n) {
        NA_character_
      } else {
        x[[n + 1 - i]]
      }
    }
    out <- map_chr(pieces, last)
    preserve_names_if_possible(string, pattern, out)
  } else {
    cli::cli_abort(tr_("{.arg i} must not be 0."))
  }
}`

const rtdal008389Source0005 = `check_positive_integer <- function(
  x,
  arg = caller_arg(x),
  call = caller_env()
) {
  if (!identical(x, Inf)) {
    check_number_whole(x, min = 1, arg = arg, call = call)
  }
}`

